using System;
using System.Collections.Generic;

class Program
{
    delegate void Next();
    delegate void Middleware(string ctx, Next next);

    static void Main()
    {
        var log = new List<string>();
        var parts = new List<Middleware>();
        // each component can act before and after next()
        parts.Add((c, next) => { log.Add("exception handler: in"); next(); log.Add("exception handler: out"); });
        parts.Add((c, next) =>
        {
            log.Add("auth: in");
            if (c == "/secret") { log.Add("auth: short-circuit 401"); return; } // no next()
            next();
            log.Add("auth: out");
        });
        parts.Add((c, next) => log.Add("endpoint: handle " + c)); // terminal (Run)

        foreach (var path in new[] { "/hello", "/secret" })
        {
            log.Clear();
            // Build() composes from last to first
            Next pipeline = () => { };
            for (int i = parts.Count - 1; i >= 0; i--)
            {
                Middleware m = parts[i];
                Next inner = pipeline;
                string p = path;
                pipeline = () => m(p, inner);
            }
            pipeline();
            Console.WriteLine("Request " + path);
            foreach (var l in log) Console.WriteLine("  " + l);
        }
    }
}

using System;
using System.Collections.Generic;

class Service { static int n; public int Id = ++n; }

class Container
{
    Dictionary<string, Service> singletons = new Dictionary<string, Service>();
    public Service Singleton()
    {
        // one instance for the whole app
        if (!singletons.ContainsKey("s")) singletons["s"] = new Service();
        return singletons["s"];
    }
    public Scope CreateScope() { return new Scope(); }
    public class Scope
    {
        Service scoped;
        // one instance per scope (per HTTP request)
        public Service Scoped() { if (scoped == null) scoped = new Service(); return scoped; }
        // new instance on every call
        public Service Transient() { return new Service(); }
    }
}

class Program
{
    static void Main()
    {
        // one root container, one scope per request
        var root = new Container();
        for (int req = 1; req <= 2; req++)
        {
            var scope = root.CreateScope();
            Console.WriteLine("Request " + req + ":");
            Console.WriteLine("  singleton ids: " + root.Singleton().Id + ", " + root.Singleton().Id);
            Console.WriteLine("  scoped ids:    " + scope.Scoped().Id + ", " + scope.Scoped().Id);
            Console.WriteLine("  transient ids: " + scope.Transient().Id + ", " + scope.Transient().Id);
        }
    }
}

using System;
using System.Collections.Generic;

class Program
{
    delegate string Handler(string arg);

    static void Main()
    {
        // tiny "minimal API": map a route template to a lambda
        var routes = new Dictionary<string, Handler>();
        routes["GET /todos/{id}"] = id => "todo " + id;
        routes["GET /health"] = x => "ok";

        // an endpoint filter wraps every handler (shared behaviour via a group)
        Func<Handler, Handler> logging = inner => a =>
        {
            Console.WriteLine("  [filter] before, arg=" + a);
            string r = inner(a);
            Console.WriteLine("  [filter] after, result=" + r);
            return r;
        };
        var group = new Dictionary<string, Handler>();
        foreach (var kv in routes) group[kv.Key] = logging(kv.Value);

        foreach (var call in new[] { "GET /todos/{id}|42", "GET /health|" })
        {
            var p = call.Split('|');
            Console.WriteLine("Call " + p[0]);
            Console.WriteLine("  => " + group[p[0]](p[1]));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    // rank per segment: lower is better. literal < constrained < parameter < catch-all
    // lower rank = more specific segment
    static int Rank(string seg)
    {
        if (seg.StartsWith("{*")) return 3;
        if (seg.StartsWith("{")) return seg.Contains(":") ? 1 : 2;
        return 0;
    }

    static bool Matches(string template, string path)
    {
        var t = template.Split('/'); var p = path.Split('/');
        for (int i = 0; i < t.Length; i++)
        {
            if (t[i].StartsWith("{*")) return true;
            if (i >= p.Length) return false;
            // a constraint only filters candidates; a failed one means 404, not 400
            if (t[i] == "{id:int}") { int x; if (!int.TryParse(p[i], out x)) return false; }
            else if (!t[i].StartsWith("{") && t[i] != p[i]) return false;
        }
        return t.Length == p.Length;
    }

    static void Main()
    {
        string[] templates = { "users/{id}", "users/{id:int}", "users/me", "{*rest}" };
        foreach (var path in new[] { "users/me", "users/7", "users/bob", "about/us" })
        {
            var cands = templates.Where(t => Matches(t, path)).ToList();
            // order by per-segment precedence, best first
            // the best (lowest) precedence string wins; an exact tie would be ambiguous
            var best = cands.OrderBy(t => string.Join("", t.Split('/').Select(s => Rank(s)))).First();
            Console.WriteLine(path.PadRight(10) + " candidates: " + string.Join(", ", cands) + " -> " + best);
        }
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // later providers override earlier ones; keys are case-insensitive
    static Dictionary<string, string> Build(params Dictionary<string, string>[] providers)
    {
        var cfg = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in providers)
            foreach (var kv in p) cfg[kv.Key.Replace("__", ":")] = kv.Value;
        return cfg;
    }

    class SmtpOptions
    {
        public string Host; public int Port;
        public void Validate()
        {
            if (string.IsNullOrEmpty(Host)) throw new Exception("Smtp:Host is required");
        }
    }

    static void Main()
    {
        var json = new Dictionary<string, string> { { "Smtp:Host", "localhost" }, { "Smtp:Port", "25" } };
        var env = new Dictionary<string, string> { { "SMTP__PORT", "587" } }; // __ becomes :
        var cfg = Build(json, env);
        foreach (var kv in cfg) Console.WriteLine(kv.Key + " = " + kv.Value);

        // options pattern: bind a section to a typed class, validate at start-up
        var o = new SmtpOptions { Host = cfg["Smtp:Host"], Port = int.Parse(cfg["Smtp:Port"]) };
        o.Validate();
        Console.WriteLine("Bound: " + o.Host + ":" + o.Port);
        try { new SmtpOptions { Host = "" }.Validate(); }
        catch (Exception e) { Console.WriteLine("Fail fast: " + e.Message); }
    }
}

