    static void Main()
    {
        // middleware sees only raw HTTP; filters run after the action is chosen
        // order in which one MVC request flows through the layers
        string[] stages = { "middleware: correlation id", "routing picks action Save(doc)",
            "authorization filter", "resource filter (before model binding)",
            "model binding", "action filter: before", "ACTION runs",
            "action filter: after", "result filter", "middleware: response headers" };
        foreach (var s in stages) Console.WriteLine(s);

        // a filter can see the bound arguments, middleware cannot
        // a filter sees the bound arguments, middleware cannot
        object[] args = { "doc-1", 42 };
        // an action filter is just a function over the arguments
        Action<object[]> actionFilter = a => Console.WriteLine("audit: action got " + a[0] + ", " + a[1]);
        actionFilter(args);
        Console.WriteLine("Ordering: authorization -> resource -> action -> exception -> result");
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // a tiny RFC 9457-style problem body
    // build a problem+json style body
    static string Problem(int status, string title, string detail, string traceId)
    {
        return "{ \"type\": \"about:blank\", \"title\": \"" + title + "\", \"status\": " + status +
               ", \"detail\": \"" + detail + "\", \"traceId\": \"" + traceId + "\" }";
    }

    // one place maps exceptions to responses (like IExceptionHandler)
    static string Handle(Exception e, string traceId)
    {
        if (e is KeyNotFoundException) return Problem(404, "Not Found", e.Message, traceId);
        if (e is ArgumentException) return Problem(400, "Bad Request", e.Message, traceId);
        return Problem(500, "Server Error", "An unexpected error occurred", traceId); // no stack trace
    }

    static void Main()
    {
        Exception[] errors = { new KeyNotFoundException("Order 9 not found"),
            new ArgumentException("qty must be positive"), new InvalidOperationException("secret db password") };
        // the trace id lets support find the matching logs
        int n = 1;
        foreach (var e in errors)
        {
            Console.WriteLine(e.GetType().Name + " -> " + Handle(e, "trace-" + n++));
        }
    }
}

using System;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static string B64(byte[] b) { return Convert.ToBase64String(b).TrimEnd('=').Replace('+', '-').Replace('/', '_'); }
    static string Sign(string data, byte[] key)
    {
        using (var h = new HMACSHA256(key)) return B64(h.ComputeHash(Encoding.UTF8.GetBytes(data)));
    }

    static string Validate(string jwt, byte[] key, long now)
    {
        var p = jwt.Split('.');
        if (Sign(p[0] + "." + p[1], key) != p[2]) return "401 bad signature";
        string payload = Encoding.UTF8.GetString(Convert.FromBase64String(
            p[1].Replace('-', '+').Replace('_', '/').PadRight((p[1].Length + 3) / 4 * 4, '=')));
        if (!payload.Contains("\"iss\":\"idp\"")) return "401 wrong issuer";
        long exp = long.Parse(payload.Split(new[] { "\"exp\":" }, StringSplitOptions.None)[1].TrimEnd('}'));
        if (now > exp + 300) return "401 expired (5 min clock skew applied)";
        return "200 ok, claims: " + payload;
    }

    static void Main()
    {
        byte[] key = Encoding.UTF8.GetBytes("demo-key-not-real");
        string head = B64(Encoding.UTF8.GetBytes("{\"alg\":\"HS256\"}"));
        string body = B64(Encoding.UTF8.GetBytes("{\"iss\":\"idp\",\"sub\":\"u1\",\"exp\":1000}"));
        string jwt = head + "." + body + "." + Sign(head + "." + body, key);
        Console.WriteLine("valid now=900:     " + Validate(jwt, key, 900));
        Console.WriteLine("expired now=1400:  " + Validate(jwt, key, 1400));
        string tampered = head + "." + B64(Encoding.UTF8.GetBytes("{\"iss\":\"idp\",\"sub\":\"admin\",\"exp\":1000}")) + "." + jwt.Split('.')[2];
        Console.WriteLine("tampered payload:  " + Validate(tampered, key, 900));
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Doc { public string OwnerId; public string Department; }
class User { public string Id; public string Role; public string Department; }

class Program
{
    delegate bool Handler(User u, Doc d);

    static void Main()
    {
        // handlers for ONE requirement are ORed: any success grants access
        var handlers = new List<Handler>();
        handlers.Add((u, d) => d.OwnerId == u.Id);                                    // owner
        handlers.Add((u, d) => u.Role == "editor" && u.Department == d.Department);  // dept editor

        var doc = new Doc { OwnerId = "alice", Department = "legal" };
        var users = new[] {
            new User { Id = "alice", Role = "viewer", Department = "legal" },
            new User { Id = "bob", Role = "editor", Department = "legal" },
            new User { Id = "carl", Role = "editor", Department = "sales" },
        };
        foreach (var u in users)
        {
            bool ok = handlers.Any(h => h(u, doc));
            Console.WriteLine(u.Id + " (" + u.Role + ", " + u.Department + ") -> " + (ok ? "200 allowed" : "403 forbidden"));
        }
    }
}

