class Context : IDisposable
{
    public bool Disposed;
    public void Dispose() { Disposed = true; }
    public string Query()
    {
        if (Disposed) throw new ObjectDisposedException("Context");
        return "rows";
    }
}

class Program
{
    static void Main()
    {
        // BUG: the singleton captures a scoped context from request 1
        Context requestScoped = new Context();
        Func<string> singletonService = () => requestScoped.Query();
        Console.WriteLine("request 1: " + singletonService());
        requestScoped.Dispose(); // the scope ends, the singleton still holds it
        try { Console.WriteLine("request 2: " + singletonService()); }
        catch (ObjectDisposedException e) { Console.WriteLine("request 2 fails: " + e.GetType().Name); }

