}

using System;
using System.Collections.Generic;

class Program
{
    static Stack<string> scopes = new Stack<string>();

    // scopes add context to every line without changing the template
    static void Log(string level, string template, params object[] args)
    {
        // the template stays constant; the values are separate structured properties
        string msg = template;
        foreach (var a in args)
        {
            int s = msg.IndexOf('{'), e = msg.IndexOf('}');
            msg = msg.Substring(0, s) + a + msg.Substring(e + 1);
        }
        Console.WriteLine(level + " [" + string.Join(" ", scopes.ToArray()) + "] " + msg + "   (template: " + template + ")");
    }

    static void Main()
    {
        // push request-wide context once
        scopes.Push("corr=abc123");   // request-wide context
        scopes.Push("user=42");
        Log("INF", "Order {OrderId} placed for {Total}", 7001, 59.90);
        Log("WRN", "Payment {Id} slow: {Ms} ms", "p9", 1200);
        scopes.Pop(); scopes.Pop();
        Log("INF", "No scope now: {Count} items", 0);
    }
}

using System;

class TokenBucket
{
    double tokens, capacity, ratePerSec, last;
    public TokenBucket(double cap, double rate) { capacity = cap; tokens = cap; ratePerSec = rate; }
    public bool TryTake(double now)
    {
        tokens = Math.Min(capacity, tokens + (now - last) * ratePerSec); // refill over time
        last = now;
        if (tokens >= 1) { tokens -= 1; return true; }
        return false; // would return 429 with Retry-After
    }
}

class Program
{
    static void Main()
    {
        var bucket = new TokenBucket(3, 1); // burst 3, 1 token per second
        double[] times = { 0, 0.1, 0.2, 0.3, 1.5, 1.6, 4.0 };
        foreach (var t in times)
            Console.WriteLine("t=" + t.ToString("0.0") + "s -> " + (bucket.TryTake(t) ? "200" : "429"));
    }
}
